package org.apache.commons.compress.compressors.bzip2;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class BZip2CompressorInputStream_read_TriageGen2Test {

    private byte[] createBzip2Data(byte[] uncompressedData) throws IOException {
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream bzipOut = 
                new org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream(baos)) {
            bzipOut.write(uncompressedData);
        }
        return baos.toByteArray();
    }

    @Test
    public void testRead_NegativeOffs() throws IOException {
        byte[] data = createBzip2Data(new byte[]{1, 2, 3});
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(data))) {
            assertThrows(IndexOutOfBoundsException.class, () -> bis.read(new byte[10], -1, 5));
        }
    }

    @Test
    public void testRead_NegativeLen() throws IOException {
        byte[] data = createBzip2Data(new byte[]{1, 2, 3});
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(data))) {
            assertThrows(IndexOutOfBoundsException.class, () -> bis.read(new byte[10], 0, -1));
        }
    }

    @Test
    public void testRead_OutOfBounds() throws IOException {
        byte[] data = createBzip2Data(new byte[]{1, 2, 3});
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(data))) {
            assertThrows(IndexOutOfBoundsException.class, () -> bis.read(new byte[5], 3, 3));
        }
    }

    @Test
    public void testRead_StreamClosed() throws IOException {
        byte[] data = createBzip2Data(new byte[]{1, 2, 3});
        BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(data));
        bis.close();
        // After close, the internal 'in' might be null or closed depending on implementation, 
        // but the code explicitly checks if (this.in == null).
        // Since we can't force 'in' to null easily without reflection, we rely on the fact that 
        // many implementations set it to null on close.
        assertThrows(IOException.class, () -> bis.read(new byte[5], 0, 2));
    }

    @Test
    public void testRead_SuccessPartial() throws IOException {
        byte[] original = {10, 20, 30, 40, 50};
        byte[] bzipData = createBzip2Data(original);
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
            byte[] dest = new byte[10];
            int read = bis.read(dest, 1, 3);
            assertEquals(3, read);
            assertEquals((byte) 20, dest[1]);
            assertEquals((byte) 30, dest[2]);
            assertEquals((byte) 40, dest[3]);
        }
    }

    @Test
    public void testRead_SuccessFull() throws IOException {
        byte[] original = {1, 2, 3};
        byte[] bzipData = createBzip2Data(original);
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
            byte[] dest = new byte[3];
            int read = bis.read(dest, 0, 3);
            assertEquals(3, read);
            assertArrayEquals(original, dest);
        }
    }

    @Test
    public void testRead_EOF() throws IOException {
        byte[] original = {1, 2};
        byte[] bzipData = createBzip2Data(original);
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
            byte[] dest = new byte[10];
            // Read all available
            bis.read(dest, 0, 2);
            // Next read should return -1
            int read = bis.read(dest, 0, 2);
            assertEquals(-1, read);
        }
    }

    @Test
    public void testRead_EmptyStream() throws IOException {
        byte[] bzipData = createBzip2Data(new byte[0]);
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
            byte[] dest = new byte[5];
            int read = bis.read(dest, 0, 5);
            assertEquals(-1, read);
        }
    }

    @Test
    public void testRead_LenZero() throws IOException {
        byte[] original = {1, 2, 3};
        byte[] bzipData = createBzip2Data(original);
        try (BZip2CompressorInputStream bis = new BZip2CompressorInputStream(new ByteArrayInputStream(bzipData))) {
            byte[] dest = new byte[5];
            int read = bis.read(dest, 0, 0);
            // According to logic: (destOffs == offs) ? -1 : (destOffs - offs)
            // If len is 0, destOffs stays equal to offs, so it returns -1
            assertEquals(-1, read);
        }
    }
}
